<script setup>import{Head,useForm}from'@inertiajs/vue3';import AuthShell from'../../Components/AuthShell.vue';import PasswordField from'../../Components/PasswordField.vue';import UiButton from'../../Components/UiButton.vue';const form=useForm({email:'',password:'',remember:false});</script><template><Head title="Sign in"/><AuthShell eyebrow="Welcome back" title="Sign in to LensPic" description="One secure sign-in for every authorized LensPic workspace."><form class="space-y-5" @submit.prevent="form.post('/login')"><label class="lp-label">Email<input v-model="form.email" type="email" autocomplete="email" class="field mt-2" required><span v-if="form.errors.email" class="lp-error">{{form.errors.email}}</span></label><PasswordField v-model="form.password" label="Password" autocomplete="current-password" :error="form.errors.password"/><div class="flex items-center justify-between gap-4"><label class="flex items-center gap-3 text-sm text-slate-600"><input v-model="form.remember" type="checkbox" class="h-4 w-4 accent-indigo">Keep me signed in</label><a href="/forgot-password" class="text-sm font-semibold text-indigo hover:underline">Forgot password?</a></div><UiButton type="submit" class="w-full" :loading="form.processing">Sign in</UiButton><p class="text-center text-sm text-slate-600">New to LensPic? <a href="/register" class="font-semibold text-indigo hover:underline">Create an account</a></p></form></AuthShell></template>
